// How many complaints to send. Keep it small: with Telegram ON, every one is a real message.
const MAX_ESCALATIONS = 5;

// 1) remove the invisible character at the start of the first column name
const clean = (r) => Object.fromEntries(Object.entries(r).map(([k, v]) => [k.replace(/^\uFEFF/, ''), v]));
// 2) put multi-line text on one line
const flat = (t) => String(t ?? '').replace(/\s+/g, ' ').trim();

const complaints = items
  .map((i) => clean(i.json))
  .filter((r) => Number(r.customer_rating) <= 2)   // only 1-2 star reviews
  .slice(0, MAX_ESCALATIONS);

return complaints.map((r, idx) => {
  const stars = Number(r.customer_rating);
  const headline = flat(r.headline);
  const review = flat(r.review);
  const text = headline === review ? review : [headline, review].filter(Boolean).join(' - ');
  return {
    json: {
      conversation_id: `jumia-${r.sku}-${idx + 1}`,
      reason: 'customer_frustrated',
      frustration_score: stars === 1 ? 9 : 7,
      channel: 'web',
      summary: `${flat(r.product_name)}: ${text}`.slice(0, 500),
    },
  };
});

// One-line summary of what the receiver answered.
const counts = {};
for (const i of items) { const s = i.json.status || ('http_' + (i.json.statusCode || '?')); counts[s] = (counts[s] || 0) + 1; }
return [{ json: { sent: items.length, results: counts } }];
